// Glowing trails: each frame starts from the previous one (iPrevFrame), drawn slightly
// smaller, turned and faded, and then new dots are drawn on top. The trails build up
// over the first few seconds.
#define PI 3.14159265

// Where dot number k (from 0 to 1) is at time t: a looping path of its own.
vec2 path(float t, float k) {
  t = t * (0.8 + 0.4 * k) + 2.0 * PI * k;
  return 0.65 * vec2(sin(t), sin(1.7 * t + 3.0 * k));
}

// The distance from p to the line segment between a and b.
float distanceToSegment(vec2 p, vec2 a, vec2 b) {
  vec2 ab = b - a;
  float h = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-6), 0.0, 1.0);
  return length(p - a - h * ab);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Coordinates with (0, 0) in the middle, and y from -1 to 1.
  vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

  // The time since the last frame, so the trails look the same at any frame rate.
  float dt = iFrame > 0 ? iTime / float(iFrame) : 1.0 / 60.0;

  // Each second, the old picture turns a little, drifts outwards and fades.
  float angle = 0.6 * dt;
  float zoom = exp(-0.8 * dt);
  float fade = exp(-1.2 * dt);
  mat2 turn = mat2(cos(angle), sin(angle), -sin(angle), cos(angle));

  // Where this pixel's colour was in the previous frame.
  vec2 prev = turn * uv * zoom;
  vec2 prevCoord = (prev * iResolution.y + iResolution.xy) / (2.0 * iResolution.xy);
  // Fade it. The small subtraction lets dim trails reach black: colours are stored in 256
  // steps, so a dark value multiplied by a number near 1 would round back to itself.
  vec3 col = max(fade * texture(iPrevFrame, prevCoord).rgb - 0.004, 0.0);

  // Five dots, each following its own looping path in its own colour. Each is drawn as a
  // streak from where its last streak ended (moved along with the old picture), so the
  // trail is unbroken.
  for (int i = 0; i < 5; i++) {
    float k = float(i) / 5.0;
    vec3 dotColor = 0.55 + 0.45 * cos(2.0 * PI * (k + vec3(0.0, 0.33, 0.67)));
    vec2 now = path(iTime, k);
    vec2 before = transpose(turn) * path(iTime - dt, k) / zoom;
    col += dotColor * smoothstep(0.04, 0.015, distanceToSegment(uv, before, now));
  }
  fragColor = vec4(min(col, 1.0), 1.0);
}
